let tabs = {}; 
let activeTabId = null;
let tabCounter = 0;
let allPlugins = []; 
let currentLang = 'en';
let activeRImageInstallDialog = null;
let _appOutputsDir = '';  // populated from backend at init — absolute path to app outputs directory
const runLogTargets = new Map(); // runId -> tabId
const runLogStreams = new Map(); // runId -> EventSource
const _tabRunState = new Map(); // tabId -> { runId, btnEl, origText, type:'linux'|'r' }
const BACKEND_PORT = Number(ipcRenderer.sendSync('get-backend-port-sync'));
if (!Number.isInteger(BACKEND_PORT) || BACKEND_PORT <= 0 || BACKEND_PORT > 65535) {
    throw new Error(`Invalid backend port received from main process: ${BACKEND_PORT}`);
}
const API_BASE = `http://127.0.0.1:${BACKEND_PORT}`;
// Keep long-lived log/docker UI traffic on a separate browser origin so long plugin
// POST requests cannot exhaust Chromium's per-origin connection pool.
const AUX_API_BASE = `http://localhost:${BACKEND_PORT}`;
const auxApiUrl = (path) => AUX_API_BASE + path;

window.addEventListener('message', async (event) => {
    const data = event && event.data ? event.data : {};
    if (!data || data.type !== 'primigenius:webapp:pickFiles') return;

    const allowedOrigins = new Set([API_BASE, AUX_API_BASE]);
    if (!allowedOrigins.has(event.origin)) return;

    const iframe = Array.from(document.querySelectorAll('iframe.webapp-iframe'))
        .find(el => el.contentWindow === event.source);
    if (!iframe) return;

    const respond = (payload) => {
        try {
            event.source.postMessage(Object.assign({
                type: 'primigenius:webapp:pickFiles:response',
                requestId: data.requestId || ''
            }, payload), event.origin);
        } catch (err) {
            console.error('[WebApp Bridge] Failed to post file picker response:', err);
        }
    };

    try {
        const raw = data.options || {};
        const properties = Array.isArray(raw.properties) && raw.properties.length
            ? raw.properties.filter(p => ['openFile', 'openDirectory', 'multiSelections'].includes(p))
            : ['openFile'];
        const filters = Array.isArray(raw.filters)
            ? raw.filters.map(f => ({
                name: String(f && f.name ? f.name : 'Files'),
                extensions: Array.isArray(f && f.extensions)
                    ? f.extensions.map(x => String(x).replace(/^\./, '')).filter(Boolean)
                    : ['*']
            })).filter(f => f.extensions.length)
            : undefined;
        const dialogOptions = {
            title: String(raw.title || 'Select file'),
            buttonLabel: raw.buttonLabel ? String(raw.buttonLabel) : undefined,
            properties,
            filters
        };
        const result = await ipcRenderer.invoke('open-file-dialog', dialogOptions);
        respond({
            ok: true,
            result: {
                canceled: !!(result && result.canceled),
                filePaths: result && Array.isArray(result.filePaths) ? result.filePaths : []
            }
        });
    } catch (err) {
        respond({ ok: false, message: err && err.message ? err.message : String(err) });
    }
});

function bindRunLogTarget(runId, tabId) {
    if (!runId || !tabId) return;
    runLogTargets.set(String(runId), String(tabId));
}

function unbindRunLogTarget(runId) {
    if (!runId) return;
    runLogTargets.delete(String(runId));
}

function parseRunTaggedLine(line) {
    const text = String(line || '');
    const m = text.match(/^\[RUN:([^\]]+)\]\s*(.*)$/);
    if (!m) return { runId: null, cleanLine: text };
    return { runId: m[1], cleanLine: m[2] || '' };
}

function startRunLogStream(runId, tabId) {
    if (!runId || !tabId) return null;
    runId = String(runId);
    tabId = String(tabId);
    bindRunLogTarget(runId, tabId);
    if (runLogStreams.has(runId)) {
        try { runLogStreams.get(runId).close(); } catch (e) {}
        runLogStreams.delete(runId);
    }
    if (typeof EventSource === 'undefined') return null;
    const url = auxApiUrl('/logs/stream?runId=' + encodeURIComponent(runId));
    const es = new EventSource(url);
    es.onmessage = (event) => {
        try {
            const payload = JSON.parse(event.data || '{}');
            if (payload.type !== 'log') return;
            appendStructuredLogLine(payload.line || '', runId, tabId);
        } catch (e) {}
    };
    es.onerror = () => {
    };
    runLogStreams.set(runId, es);
    return es;
}

function finishRunLogStream(runId) {
    if (!runId) return;
    runId = String(runId);
    const es = runLogStreams.get(runId);
    setTimeout(() => {
        if (es) {
            try { es.close(); } catch (e) {}
        }
        runLogStreams.delete(runId);
        unbindRunLogTarget(runId);
    }, 1500);
}

