// 翻译函数
function t(key) {
    return i18nData[currentLang][key] || key;
}

// 获取插件配置中的多语言文本 (支持 string 或 {zh:.., en:..})
function getPluginText(obj) {
    if (!obj) return "";
    if (typeof obj === 'string') return obj;
    if (typeof obj === 'object') {
        return obj[currentLang] || obj['en'] || obj['zh'] || 'Unknown';
    }
    return String(obj);
}

function getCategoryLabel(cat) {
    if (!cat) return t('unknown_category');
    if (typeof cat === 'string') return cat;
    return getPluginText(cat) || t('unknown_category');
}

function shouldShowJavaBadge(cfg) {
    return !!(cfg && (cfg.java_app || cfg.java_version || cfg.java_badge));
}

// 切换语言
function buildPluginTitleHtml(cfg) {
    const mode = cfg.execution_mode || 'loop';
    let modeBadge = '';
    if (cfg.run_mode !== 'native_gui' && cfg.run_mode !== 'webapp') {
        if (mode === 'merge') {
            const label = currentLang === 'zh' ? '合并' : 'Merge';
            modeBadge = `<span style="background:#e3f2fd; color:#0d47a1; padding:4px 8px; border-radius:4px; font-size:12px; margin-left:10px; border:1px solid #90caf9; font-weight:600;"><i class="fas fa-layer-group"></i> ${label}</span>`;
        } else {
            const label = currentLang === 'zh' ? '循环' : 'Loop';
            modeBadge = `<span style="background:#e8f0fe; color:#1976d2; padding:4px 8px; border-radius:4px; font-size:12px; margin-left:10px; border:1px solid #bbdefb; font-weight:600;"><i class="fas fa-sync-alt"></i> ${label}</span>`;
        }
    }

    let runtimeBadge = '';
    if ((cfg.run_mode === 'native_gui' || cfg.run_mode === 'native_java_cli') && shouldShowJavaBadge(cfg)) {
        runtimeBadge = `<span style="background:#fff3e0; color:#e65100; padding:4px 8px; border-radius:4px; font-size:12px; margin-left:6px; border:1px solid #ffcc80; font-weight:600;"><i class="fas fa-coffee" style="margin-right:3px;"></i>Java</span>`;
    }

    let packageBadge = '';
    const isLinuxPlugin = !(cfg.type && String(cfg.type).toLowerCase().startsWith('r'));
    if (isLinuxPlugin && cfg.docker_image && cfg.run_mode !== 'native_gui' && cfg.run_mode !== 'webapp' && cfg.run_mode !== 'native_java_cli') {
        packageBadge = `<span class="docker-image-badge" data-plugin-id="${cfg.id}" data-current-image="${escapeHtml(cfg.docker_image)}" style="background:#e3f2fd; color:#1976d2; padding:4px 8px; border-radius:4px; font-size:12px; margin-left:6px; border:1px solid #bbdefb; cursor:pointer; position:relative;" title="${currentLang==='zh'?'点击切换镜像':'Click to switch image'}"><i class="fas fa-cube" style="margin-right:3px;"></i>${escapeHtml(cfg.docker_image)}</span>`;
    }

    let runModeBadge = '<span class="linux-badge"><i class="fab fa-linux"></i> Linux</span>';
    if (cfg.run_mode === 'native_gui') {
        runModeBadge = '<span class="linux-badge" style="background:#e8f5e9;color:#2e7d32;border-color:#a5d6a7;"><i class="fas fa-desktop"></i> GUI</span>';
    } else if (cfg.run_mode === 'native_java_cli') {
        runModeBadge = '<span class="linux-badge" style="background:#fff8e1;color:#8a5a00;border-color:#ffe082;"><i class="fas fa-terminal"></i> Java CLI</span>';
    } else if (cfg.run_mode === 'webapp') {
        runModeBadge = '<span class="linux-badge" style="background:#e3f2fd;color:#1565c0;border-color:#90caf9;"><i class="fas fa-globe"></i> WebApp</span>';
    }

    return `${getPluginText(cfg.name)} ${runModeBadge} ${modeBadge} ${runtimeBadge} ${packageBadge}`;
}

function _formatWorkflowInfoValue(value) {
    if (value === null || value === undefined || value === '') return currentLang === 'zh' ? '（空）' : '(empty)';
    if (typeof value === 'boolean') return value ? (currentLang === 'zh' ? '是' : 'Yes') : (currentLang === 'zh' ? '否' : 'No');
    if (typeof value === 'object') {
        try { return JSON.stringify(value); } catch (e) { return String(value); }
    }
    return String(value);
}

function _workflowParameterDefaultValue(param) {
    if (!param) return undefined;
    if (param.type === 'checkbox') {
        const checked = param.default !== undefined
            ? !!param.default
            : (param.checked !== undefined ? !!param.checked : false);
        return checked ? (param.value || true) : false;
    }
    return param.default !== undefined ? param.default : '';
}

function _workflowParameterValuesEqual(left, right) {
    const normalize = value => {
        if (value === null || value === undefined || value === '') return '';
        if (Array.isArray(value)) return value.map(normalize);
        if (typeof value === 'object') {
            const sorted = {};
            Object.keys(value).sort().forEach(key => { sorted[key] = normalize(value[key]); });
            return sorted;
        }
        if (typeof value === 'boolean') return value;
        return String(value);
    };
    try { return JSON.stringify(normalize(left)) === JSON.stringify(normalize(right)); }
    catch (e) { return String(left ?? '') === String(right ?? ''); }
}

function _isWorkflowParameterModified(param, value) {
    if (!param) return false;
    return !_workflowParameterValuesEqual(value, _workflowParameterDefaultValue(param));
}

function _refreshWorkflowInfoPanelLanguage(panel) {
    const zh = currentLang === 'zh';
    const title = panel.querySelector('[data-wf-info-i18n="title"]');
    const notesTitle = panel.querySelector('[data-wf-info-i18n="notes"]');
    const paramsTitle = panel.querySelector('[data-wf-info-i18n="parameters"]');
    const toggle = panel.querySelector('.wf-info-panel-toggle');
    if (title) title.textContent = zh ? '工作流说明' : 'Workflow Information';
    if (notesTitle) notesTitle.textContent = zh ? '说明信息' : 'Notes';
    if (paramsTitle) paramsTitle.textContent = zh ? '参数信息' : 'Parameters';
    if (toggle) {
        const collapsed = panel.classList.contains('collapsed');
        toggle.title = collapsed
            ? (zh ? '展开工作流说明' : 'Expand workflow information')
            : (zh ? '折叠为悬浮球' : 'Collapse to floating button');
        toggle.setAttribute('aria-label', toggle.title);
    }

    panel.querySelectorAll('.wf-info-panel-param-group').forEach(group => {
        const plugin = allPlugins.find(item => item.id === group.dataset.pluginId);
        const pluginName = group.querySelector('.wf-info-panel-param-plugin-name');
        if (pluginName) pluginName.textContent = plugin ? getPluginText(plugin.name) : (group.dataset.pluginId || '');
        group.querySelectorAll('.wf-info-panel-param-row').forEach(row => {
            const paramId = row.dataset.paramId || '';
            const param = plugin && (plugin.parameters || []).find(item =>
                (item.id || item.name || JSON.stringify(item)) === paramId
            );
            const label = row.querySelector('.wf-info-panel-param-label-text');
            const value = row.querySelector('.wf-info-panel-param-value');
            if (label) label.textContent = param ? getPluginText(param.label || paramId) : paramId;
            if (value) {
                value.textContent = _formatWorkflowInfoValue(row._workflowInfoRawValue);
                value.title = value.textContent;
            }
            if (row.classList.contains('is-modified')) {
                const defaultText = _formatWorkflowInfoValue(row._workflowInfoDefaultValue);
                row.title = zh
                    ? `此参数值与当前插件默认值不同；默认值：${defaultText}`
                    : `This value differs from the current plugin default. Default: ${defaultText}`;
                if (value) value.title = row.title;
            }
        });
    });
}

