// 聚焦问题。
(function _initInertGuard() {
    // 这些元素永远不应被 inert — 即使 dialog 正在打开
    const NEVER_INERT_IDS = new Set(['main-container', 'tab-bar-container', 'top-nav']);
    const hasOpenDialog = () => !!document.querySelector('dialog[open]');

    function removeInertFrom(el) {
        el.removeAttribute('inert');
        el.removeAttribute('aria-hidden');
    }

    function cleanStaleInert() {
        // 始终保护关键容器 — 无论 dialog 是否打开
        NEVER_INERT_IDS.forEach(id => {
            const el = document.getElementById(id);
            if (el && el.hasAttribute('inert')) {
                removeInertFrom(el);
            }
        });
        // 如果没有 dialog 打开，清理所有残留 inert
        if (!hasOpenDialog()) {
            document.querySelectorAll('[inert]').forEach(el => {
                el.removeAttribute('inert');
            });
            document.querySelectorAll('[aria-hidden="true"]').forEach(el => {
                if (!el.closest('dialog[open]')) el.removeAttribute('aria-hidden');
            });
        }
    }
    // 窗口回焦时清理
    window.addEventListener('focus', cleanStaleInert);
    // 鼠标按下时清理 (capture phase，在 inert 阻止事件之前)
    document.addEventListener('mousedown', cleanStaleInert, true);
    // MutationObserver 实时拦截 — 关键容器 inert 立即移除
    const obs = new MutationObserver((muts) => {
        for (const m of muts) {
            if (m.type === 'attributes' && m.attributeName === 'inert' && m.target.hasAttribute('inert')) {
                // 关键容器：立即移除 inert，不管 dialog 状态
                if (NEVER_INERT_IDS.has(m.target.id)) {
                    m.target.removeAttribute('inert');
                    continue;
                }
                // 其他元素：仅在没有 dialog 打开时移除
                if (!hasOpenDialog()) {
                    m.target.removeAttribute('inert');
                }
            }
        }
    });
    // 直接监控 body subtree，避免重复注册 observer
    obs.observe(document.body, { subtree: true, attributes: true, attributeFilter: ['inert'] });
    // 启动后立即清理一次
    cleanStaleInert();

    // 全局监听 dialog close 事件 — 任何对话框关闭后立即清理 inert
    document.addEventListener('close', () => {
        requestAnimationFrame(() => {
            ['main-container', 'tab-bar-container', 'top-nav'].forEach(id => {
                const el = document.getElementById(id);
                if (el) { el.removeAttribute('inert'); el.removeAttribute('aria-hidden'); }
            });
            // 清理无 [open] 的残留 dialog 节点
            document.querySelectorAll('dialog:not([open]):not(.r-image-install-dialog-minimized)').forEach(d => {
                if (!d.closest('#main-container')) { try { d.remove(); } catch(e){} }
            });
        });
    }, true);
})();

function restoreWebContentsFocus(reason) {
    try {
        if (document.visibilityState !== 'visible') return;
        ipcRenderer.send('force-webcontents-focus', reason || 'renderer');
    } catch (e) {}
}

let __focusRestoreRaf = 0;
let __focusRestoreTimer = null;
let __lastImmediateFocusRestoreAt = 0;

function scheduleWebContentsFocusRestore(reason) {
    const tag = reason || 'renderer';
    const now = Date.now();

    // 立即恢复（节流），保证关键交互仍及时
    if (now - __lastImmediateFocusRestoreAt > 120) {
        restoreWebContentsFocus(tag);
        __lastImmediateFocusRestoreAt = now;
    }

    // 合并重复触发，减少 IPC 风暴
    if (__focusRestoreRaf) cancelAnimationFrame(__focusRestoreRaf);
    __focusRestoreRaf = requestAnimationFrame(() => {
        __focusRestoreRaf = 0;
        restoreWebContentsFocus(`${tag}:raf`);
    });

    if (__focusRestoreTimer) clearTimeout(__focusRestoreTimer);
    __focusRestoreTimer = setTimeout(() => {
        __focusRestoreTimer = null;
        restoreWebContentsFocus(`${tag}:t120`);
    }, 120);
}

