// --- D. 社区交流面板 (GitHub Discussions GraphQL API) ---
// GitHub OAuth Device Flow client ID.
const GITHUB_COMMUNITY = {
    owner: 'jianbai-design',
    repo: 'PrimiGenius',
    perPage: 20,
    clientId: 'Ov23liZOLYKETwBJgtxk'
};

const GITHUB_DISCUSSION_CATEGORY_ZH = {
    'Announcements': '公告',
    'General': '综合',
    'Ideas': '想法',
    'Polls': '投票',
    'Q&A': '问答',
    'Show and tell': '作品展示'
};

function _localizeDiscussionCategoryName(name) {
    if (currentLang !== 'zh') return name || '';
    return GITHUB_DISCUSSION_CATEGORY_ZH[name] || name || '';
}

let _ghCommunityMeta = null;
let _ghPinnedDiscussionCache = { ts: 0, numbers: [] };
const _ghCommunityFeedCache = new Map();
const GH_COMMUNITY_FEED_CACHE_TTL = 45000;
const GH_PUBLIC_PROXY_PREFIXES = [
    // Add only proxies verified to return JSON for api.github.com.
];

function _escapeRegex(s) {
    return String(s || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function _parsePinnedDiscussionNumbersFromHtml(html) {
    const text = String(html || '');
    const start = text.search(/id="pinned-discussions"/i);
    if (start < 0) return [];
    const tail = text.slice(start, start + 180000);
    const end = tail.search(/id="discussions"|aria-label="Discussions"|>Discussions<|id="categories"/i);
    const section = end > 0 ? tail.slice(0, end) : tail;
    const p = `/${_escapeRegex(GITHUB_COMMUNITY.owner)}/${_escapeRegex(GITHUB_COMMUNITY.repo)}/discussions/(\\d+)`;
    const re = new RegExp(p, 'gi');
    const set = new Set();
    let m;
    while ((m = re.exec(section))) {
        const n = Number(m[1]);
        if (Number.isFinite(n)) set.add(n);
    }
    return Array.from(set);
}

function _fetchTextViaHttps(url) {
    return new Promise((resolve, reject) => {
        let https;
        try {
            https = require('https');
        } catch (e) {
            reject(e);
            return;
        }
        const req = https.request(url, {
            method: 'GET',
            headers: {
                'User-Agent': 'PrimiGenius/1.0',
                'Accept': 'text/html,application/xhtml+xml'
            }
        }, (res) => {
            const code = Number(res.statusCode || 0);
            if (code >= 300 && code < 400 && res.headers && res.headers.location) {
                res.resume();
                _fetchTextViaHttps(res.headers.location).then(resolve).catch(reject);
                return;
            }
            if (code < 200 || code >= 300) {
                res.resume();
                reject(new Error(`HTTP ${code}`));
                return;
            }
            let body = '';
            res.setEncoding('utf8');
            res.on('data', chunk => body += chunk);
            res.on('end', () => resolve(body));
        });
        req.on('error', reject);
        req.end();
    });
}

// Get stored OAuth token from localStorage, or null
function _ghGetToken() {
    return localStorage.getItem('gh_oauth_token') || '';
}
function _ghSetToken(token) {
    localStorage.setItem('gh_oauth_token', token);
}
function _ghGetUser() {
    try { return JSON.parse(localStorage.getItem('gh_oauth_user') || 'null'); } catch(e) { return null; }
}
function _ghSetUser(user) {
    localStorage.setItem('gh_oauth_user', user ? JSON.stringify(user) : '');
}
function _ghClearAuth() {
    localStorage.removeItem('gh_oauth_token');
    localStorage.removeItem('gh_oauth_user');
}

function _ghHeaders() {
    const h = { 'Accept': 'application/vnd.github+json' };
    const token = _ghGetToken();
    if (token) h['Authorization'] = `token ${token}`;
    return h;
}

function _ghHttpError(resp) {
    const status = Number(resp && resp.status ? resp.status : 0);
    const remaining = _ghGetHeader(resp && resp.headers, 'x-ratelimit-remaining');
    if ((status === 403 || status === 429) && String(remaining) === '0') {
        const resetSeconds = Number(_ghGetHeader(resp && resp.headers, 'x-ratelimit-reset'));
        const hasResetTime = Number.isFinite(resetSeconds) && resetSeconds > 0;
        const resetTime = hasResetTime
            ? new Date(resetSeconds * 1000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            : '';
        const resetHint = resetTime
            ? (currentLang === 'zh' ? `（预计 ${resetTime} 恢复）` : ` (expected to reset at ${resetTime})`)
            : '';
        if (!_ghGetToken()) {
            return new Error(currentLang === 'zh'
                ? `GitHub 匿名请求额度已用完${resetHint}，请点击页面右上角“登录”并登录 GitHub 后重试。`
                : `The GitHub anonymous request limit has been reached${resetHint}. Please click “Sign in” in the upper-right corner and sign in to GitHub, then retry.`);
        }
        return new Error(currentLang === 'zh'
            ? `GitHub API 请求额度已用完${resetHint}，请稍后重试。`
            : `The GitHub API request limit has been reached${resetHint}. Please retry later.`);
    }
    return new Error(`HTTP ${status}`);
}

let _ghNetworkModeCache = { mode: 'auto', ts: 0 };

function _ghIsRetryableStatus(status) {
    return [408, 425, 429, 500, 502, 503, 504].includes(Number(status || 0));
}

function _ghNetworkPolicyByMode(mode) {
    const m = String(mode || 'auto').toLowerCase();
    if (m === 'cn') {
        return { mode: 'cn', timeoutMs: 3800, retries: 3, backoffMs: 700, perPage: 12 };
    }
    if (m === 'global') {
        return { mode: 'global', timeoutMs: 9000, retries: 1, backoffMs: 900, perPage: GITHUB_COMMUNITY.perPage };
    }
    return { mode: 'auto', timeoutMs: 6500, retries: 2, backoffMs: 800, perPage: 16 };
}

async function _ghGetNetworkMode() {
    const now = Date.now();
    if (_ghNetworkModeCache.mode && (now - _ghNetworkModeCache.ts) < 12000) {
        return _ghNetworkModeCache.mode;
    }
    try {
        const resp = await fetch(auxApiUrl('/podman/network-profile'), { cache: 'no-store' });
        if (resp.ok) {
            const data = await resp.json().catch(() => ({}));
            const mode = (data && data.mode) ? String(data.mode) : 'auto';
            _ghNetworkModeCache = { mode, ts: now };
            return mode;
        }
    } catch (e) {}
    _ghNetworkModeCache = { mode: 'auto', ts: now };
    return 'auto';
}

function _ghGetHeader(headers, name) {
    if (!headers) return '';
    if (typeof Headers !== 'undefined' && headers instanceof Headers) {
        return headers.get(name) || '';
    }
    const target = String(name || '').toLowerCase();
    for (const key of Object.keys(headers || {})) {
        if (String(key).toLowerCase() === target) return headers[key] || '';
    }
    return '';
}

function _ghFetchMethod(options) {
    return String((options && options.method) || 'GET').toUpperCase();
}

function _ghCanProxyFetch(url, options, mode) {
    if (String(mode || '').toLowerCase() !== 'cn') return false;
    if (_ghFetchMethod(options) !== 'GET') return false;
    if (_ghGetHeader((options || {}).headers, 'Authorization')) return false;
    try {
        const parsed = new URL(url);
        return parsed.protocol === 'https:' && parsed.hostname === 'api.github.com';
    } catch (e) {
        return false;
    }
}

function _ghFetchCandidateUrls(url, options, mode) {
    if (!_ghCanProxyFetch(url, options, mode)) return [url];
    const out = GH_PUBLIC_PROXY_PREFIXES.map(prefix => `${prefix}${url}`);
    out.push(url);
    return Array.from(new Set(out));
}

function _ghFetchOnce(url, options, timeoutMs, externalController) {
    const ac = externalController || new AbortController();
    const timer = setTimeout(() => ac.abort(), timeoutMs);
    return fetch(url, { ...(options || {}), signal: ac.signal })
        .finally(() => clearTimeout(timer));
}

async function _ghFetchFastest(urls, options, timeoutMs) {
    const controllers = [];
    const attempts = (urls || []).map((url, index) => {
        const ac = new AbortController();
        controllers[index] = ac;
        return _ghFetchOnce(url, options, timeoutMs, ac).then(resp => {
            if (!resp.ok) throw _ghHttpError(resp);
            return { resp, index };
        });
    });
    const winner = await Promise.any(attempts);
    controllers.forEach((ac, index) => {
        if (index !== winner.index) {
            try { ac.abort(); } catch (e) {}
        }
    });
    return winner.resp;
}

async function _ghFetch(url, options, cfg) {
    const mode = await _ghGetNetworkMode();
    const policy = _ghNetworkPolicyByMode(mode);
    const timeoutMs = Number((cfg && cfg.timeoutMs) || policy.timeoutMs);
    const retries = Number((cfg && cfg.retries) ?? policy.retries);
    const backoffMs = Number((cfg && cfg.backoffMs) || policy.backoffMs);
    const retryOnHttp = (cfg && cfg.retryOnHttp) || _ghIsRetryableStatus;
    const allowRetry = !(cfg && cfg.noRetry);

    let lastErr = null;
    for (let i = 0; i <= retries; i++) {
        try {
            const candidateUrls = _ghFetchCandidateUrls(url, options, mode);
            const resp = candidateUrls.length > 1
                ? await _ghFetchFastest(candidateUrls, options, timeoutMs)
                : await _ghFetchOnce(url, options, timeoutMs);
            const canRetryHttp = allowRetry && i < retries && typeof retryOnHttp === 'function' && retryOnHttp(resp.status);
            if (canRetryHttp) {
                await new Promise(r => setTimeout(r, backoffMs * (i + 1)));
                continue;
            }
            return resp;
        } catch (e) {
            lastErr = e;
            if (!allowRetry || i >= retries) break;
            await new Promise(r => setTimeout(r, backoffMs * (i + 1)));
        }
    }
    if (lastErr && lastErr.name === 'AggregateError' && Array.isArray(lastErr.errors) && lastErr.errors.length) {
        lastErr = lastErr.errors[0];
    }
    if (lastErr && lastErr.name === 'AbortError') {
        throw new Error(currentLang === 'zh' ? '网络请求超时，请稍后重试' : 'Request timed out, please retry');
    }
    throw lastErr || new Error(currentLang === 'zh' ? '网络请求失败' : 'Network request failed');
}

async function _ghFetchJson(url, options, cfg) {
    const resp = await _ghFetch(url, options, cfg);
    const data = await resp.json().catch(() => ({}));
    return { resp, data };
}

async function _ghGraphQL(query, variables, requireAuth) {
    const token = _ghGetToken();
    if (requireAuth && !token) {
        throw new Error(currentLang === 'zh' ? '需要登录 GitHub 才能执行该操作' : 'GitHub login required for this action');
    }

    const headers = {
        'Accept': 'application/vnd.github+json',
        'Content-Type': 'application/json'
    };
    if (token) headers['Authorization'] = `bearer ${token}`;

    const resp = await _ghFetch('https://api.github.com/graphql', {
        method: 'POST',
        headers,
        body: JSON.stringify({ query, variables: variables || {} })
    }, { retries: 2 });

    const payload = await resp.json().catch(() => ({}));
    const errs = Array.isArray(payload.errors) ? payload.errors : [];
    if (!resp.ok || errs.length > 0) {
        const msg = errs[0] && errs[0].message ? errs[0].message : `HTTP ${resp.status}`;
        throw new Error(msg);
    }
    return payload.data || {};
}

async function _ghLoadCommunityMeta() {
    const q = `
        query($owner: String!, $repo: String!) {
            repository(owner: $owner, name: $repo) {
                id
                discussionCategories(first: 50) {
                    nodes {
                        id
                        name
                        description
                        isAnswerable
                        emoji
                    }
                }
            }
        }
    `;
    const data = await _ghGraphQL(q, { owner: GITHUB_COMMUNITY.owner, repo: GITHUB_COMMUNITY.repo }, true);
    const repo = data.repository;
    if (!repo || !repo.id) throw new Error(currentLang === 'zh' ? '无法读取 Discussions 仓库信息' : 'Failed to load Discussions repository metadata');
    _ghCommunityMeta = {
        repositoryId: repo.id,
        categories: (repo.discussionCategories && repo.discussionCategories.nodes) ? repo.discussionCategories.nodes : []
    };
    return _ghCommunityMeta;
}

async function _ghLoadPinnedDiscussionNumbers(forceRefresh) {
    const token = _ghGetToken();
    if (!token) return [];
    const now = Date.now();
    if (!forceRefresh && _ghPinnedDiscussionCache.numbers.length && (now - _ghPinnedDiscussionCache.ts) < 60000) {
        return _ghPinnedDiscussionCache.numbers;
    }
    const q = `
        query($owner: String!, $repo: String!) {
            repository(owner: $owner, name: $repo) {
                pinnedDiscussions(first: 20) {
                    nodes {
                        number
                    }
                }
            }
        }
    `;
    try {
        const data = await _ghGraphQL(q, { owner: GITHUB_COMMUNITY.owner, repo: GITHUB_COMMUNITY.repo }, true);
        const nodes = (((data || {}).repository || {}).pinnedDiscussions || {}).nodes || [];
        const numbers = nodes.map(n => Number(n.number)).filter(n => Number.isFinite(n));
        if (numbers.length > 0) {
            _ghPinnedDiscussionCache = { ts: now, numbers };
            return numbers;
        }
    } catch (e) {
        // Ignore and continue with HTML fallback for public repos.
    }

    try {
        const pageUrl = `https://github.com/${GITHUB_COMMUNITY.owner}/${GITHUB_COMMUNITY.repo}/discussions`;
        const html = await _fetchTextViaHttps(pageUrl);
        const numbers = _parsePinnedDiscussionNumbersFromHtml(html);
        _ghPinnedDiscussionCache = { ts: now, numbers };
        return numbers;
    } catch (e) {
        _ghPinnedDiscussionCache = { ts: now, numbers: [] };
        return [];
    }
}

// GitHub Device Flow login
async function ghDeviceLogin() {
    const zh = currentLang === 'zh';
    if (!GITHUB_COMMUNITY.clientId) {
        alert(zh
            ? '未配置 GitHub OAuth App Client ID。'
            : 'GitHub OAuth App Client ID not configured.');
        return null;
    }
    return new Promise((resolve) => {
        const dlg = document.createElement('dialog');
        dlg.style.cssText = 'border:none;border-radius:14px;padding:0;background:#fff;box-shadow:0 8px 40px rgba(0,0,0,0.3);z-index:200000;min-width:420px;max-width:500px;';

        dlg.innerHTML = `
            <div style="padding:18px 24px 12px;font-size:17px;font-weight:700;color:#333;border-bottom:1px solid #eee;display:flex;align-items:center;gap:10px;">
                <i class="fab fa-github" style="font-size:24px;color:#24292e;"></i>
                ${zh?'登录 GitHub':'Sign in to GitHub'}
            </div>
            <div style="padding:24px;text-align:center;">
                <i class="fas fa-spinner fa-spin" style="font-size:28px;color:#1976d2;"></i>
                <div style="margin-top:12px;color:#666;font-size:14px;">${zh?'正在请求授权码…':'Requesting authorization code…'}</div>
            </div>
        `;
        const closeDlg = (result) => { try{dlg.close();}catch(e){} try{dlg.remove();}catch(e){} resolve(result); };
        dlg.addEventListener('cancel', e => { e.preventDefault(); closeDlg(null); });
        document.body.appendChild(dlg);
        dlg.showModal();

        (async () => {
            try {
                // Request device code
                const codeResp = await _ghFetch('https://github.com/login/device/code', {
                    method: 'POST',
                    headers: { 'Accept': 'application/json', 'Content-Type': 'application/json' },
                    body: JSON.stringify({ client_id: GITHUB_COMMUNITY.clientId, scope: 'public_repo read:discussion write:discussion read:user' })
                }, { retries: 3, timeoutMs: 4500 });
                if (!codeResp.ok) throw new Error(`HTTP ${codeResp.status}`);
                const codeData = await codeResp.json();
                const { device_code, user_code, verification_uri, expires_in, interval } = codeData;

                // Auto-copy code to clipboard
                try { require('electron').clipboard.writeText(user_code); } catch(e) { navigator.clipboard.writeText(user_code).catch(()=>{}); }

                // Open in-app browser window directly
                const verifyUrl = `${verification_uri}?user_code=${encodeURIComponent(user_code)}`;
                try { await ipcRenderer.invoke('open-github-auth', { url: verifyUrl, userCode: user_code }); } catch(e) {}

                dlg.innerHTML = `
                    <div style="padding:18px 24px 12px;font-size:17px;font-weight:700;color:#333;border-bottom:1px solid #eee;display:flex;align-items:center;gap:10px;">
                        <i class="fab fa-github" style="font-size:24px;color:#24292e;"></i>
                        ${zh?'登录 GitHub':'Sign in to GitHub'}
                    </div>
                    <div style="padding:24px;text-align:center;">
                        <div style="font-size:14px;color:#555;line-height:1.7;margin-bottom:16px;">
                            ${zh?'已在应用内打开 GitHub 授权页面，请在弹出的窗口中完成登录。':'GitHub authorization page has been opened. Please complete login in the popup window.'}
                        </div>
                        <div style="margin:12px 0 8px;font-size:13px;color:#888;">${zh?'授权码（已自动复制到剪贴板）：':'Authorization code (copied to clipboard):'}</div>
                        <div class="gh-user-code" style="font-size:32px;font-weight:800;letter-spacing:6px;color:#1976d2;font-family:Consolas,'Courier New',monospace;background:#e3f2fd;padding:12px 28px;border-radius:10px;display:inline-block;cursor:pointer;user-select:all;" title="${zh?'点击复制':'Click to copy'}">${user_code}</div>
                        <div style="margin-top:8px;font-size:12px;color:#2e7d32;"><i class="fas fa-check-circle"></i> ${zh?'已复制到剪贴板，在授权页面中粘贴即可':'Copied! Paste it in the authorization page'}</div>
                        <div style="margin-top:20px;display:flex;align-items:center;justify-content:center;gap:8px;color:#888;font-size:13px;">
                            <i class="fas fa-spinner fa-spin" style="color:#1976d2;"></i>
                            ${zh?'等待授权中…完成后将自动登录':'Waiting for authorization… will auto-login when done'}
                        </div>
                        <div style="margin-top:12px;display:flex;justify-content:center;gap:8px;flex-wrap:wrap;">
                            <button class="gh-reopen-btn" style="background:none;border:1px solid #ccc;border-radius:6px;padding:5px 12px;cursor:pointer;font-size:12px;color:#555;"><i class="fas fa-redo"></i> ${zh?'重新打开授权页面':'Reopen auth page'}</button>
                            <button class="gh-open-browser-btn" style="background:none;border:1px solid #90caf9;border-radius:6px;padding:5px 12px;cursor:pointer;font-size:12px;color:#1565c0;"><i class="fas fa-external-link-alt"></i> ${zh?'系统浏览器打开':'Open in browser'}</button>
                        </div>
                    </div>
                    <div style="padding:8px 24px 18px;display:flex;justify-content:flex-end;">
                        <button class="dlg-cancel" style="padding:8px 18px;border-radius:6px;border:1px solid #ccc;background:#f5f5f5;cursor:pointer;font-size:13px;">${zh?'取消':'Cancel'}</button>
                    </div>
                `;

                // Copy code on click
                dlg.querySelector('.gh-user-code').onclick = () => {
                    try { require('electron').clipboard.writeText(user_code); } catch(e) { navigator.clipboard.writeText(user_code).catch(()=>{}); }
                    const el = dlg.querySelector('.gh-user-code');
                    el.style.background = '#c8e6c9'; el.style.color = '#2e7d32';
                    setTimeout(() => { el.style.background = '#e3f2fd'; el.style.color = '#1976d2'; }, 1000);
                };

                // Reopen auth window button
                dlg.querySelector('.gh-reopen-btn').onclick = async () => {
                    try { await ipcRenderer.invoke('open-github-auth', { url: verifyUrl, userCode: user_code }); } catch(e) {}
                };
                const openBrowserBtn = dlg.querySelector('.gh-open-browser-btn');
                if (openBrowserBtn) openBrowserBtn.onclick = () => {
                    try { require('electron').shell.openExternal(verifyUrl); } catch(e) { window.open(verifyUrl, '_blank'); }
                };

                dlg.querySelector('.dlg-cancel').onclick = () => closeDlg(null);

                const pollInterval = (interval || 5) * 1000;
                const deadline = Date.now() + (expires_in || 900) * 1000;
                let cancelled = false;
                dlg.addEventListener('cancel', () => { cancelled = true; try { ipcRenderer.invoke('close-github-auth'); } catch(e) {} });

                while (Date.now() < deadline && !cancelled) {
                    await new Promise(r => setTimeout(r, pollInterval));
                    if (cancelled) break;
                    try {
                        const tokenResp = await _ghFetch('https://github.com/login/oauth/access_token', {
                            method: 'POST',
                            headers: { 'Accept': 'application/json', 'Content-Type': 'application/json' },
                            body: JSON.stringify({
                                client_id: GITHUB_COMMUNITY.clientId,
                                device_code,
                                grant_type: 'urn:ietf:params:oauth:grant-type:device_code'
                            })
                        }, { retries: 1, timeoutMs: 5000 });
                        const tokenData = await tokenResp.json();
                        if (tokenData.access_token) {
                            _ghSetToken(tokenData.access_token);
                            // Close in-app auth window
                            try { await ipcRenderer.invoke('close-github-auth'); } catch(e) {}
                            // Fetch user info
                            try {
                                const userResp = await _ghFetch('https://api.github.com/user', {
                                    headers: { 'Authorization': `token ${tokenData.access_token}`, 'Accept': 'application/vnd.github.v3+json' }
                                }, { retries: 2, timeoutMs: 5000 });
                                if (userResp.ok) {
                                    const userData = await userResp.json();
                                    _ghSetUser({ login: userData.login, avatar_url: userData.avatar_url, name: userData.name || userData.login });
                                }
                            } catch(e) {}
                            closeDlg(tokenData.access_token);
                            return;
                        }
                        if (tokenData.error === 'expired_token' || tokenData.error === 'access_denied') {
                            try { await ipcRenderer.invoke('close-github-auth'); } catch(e) {}
                            closeDlg(null);
                            return;
                        }
                        // 'authorization_pending' or 'slow_down' → keep polling
                        if (tokenData.error === 'slow_down') {
                            await new Promise(r => setTimeout(r, 5000));
                        }
                    } catch(e) { /* network error, keep polling */ }
                }
                try { await ipcRenderer.invoke('close-github-auth'); } catch(e) {}
                closeDlg(null);
            } catch(e) {
                try { ipcRenderer.invoke('close-github-auth'); } catch(e2) {}
                dlg.innerHTML = `
                    <div style="padding:18px 24px 12px;font-size:17px;font-weight:700;color:#e53935;border-bottom:1px solid #eee;">
                        <i class="fas fa-exclamation-triangle"></i> ${zh?'授权失败':'Authorization Failed'}
                    </div>
                    <div style="padding:24px;color:#666;font-size:14px;">${e.message}</div>
                    <div style="padding:8px 24px 18px;display:flex;justify-content:flex-end;">
                        <button class="dlg-cancel" style="padding:8px 18px;border-radius:6px;border:1px solid #ccc;background:#f5f5f5;cursor:pointer;font-size:13px;">${zh?'关闭':'Close'}</button>
                    </div>
                `;
                dlg.querySelector('.dlg-cancel').onclick = () => closeDlg(null);
            }
        })();
    });
}

// Ensure user is logged in; returns token or null
async function ghEnsureAuth() {
    const token = _ghGetToken();
    if (token) {
        // Verify token is still valid
        try {
            const resp = await _ghFetch('https://api.github.com/user', { headers: { 'Authorization': `token ${token}`, 'Accept': 'application/vnd.github.v3+json' } }, { retries: 1, timeoutMs: 5000 });
            if (resp.ok) return token;
            // Token expired/revoked
            _ghClearAuth();
        } catch(e) {}
    }
    return await ghDeviceLogin();
}

